"""RoboPaint eai-standard/2.2 live trajectory driver for the single 鳳 episode."""
import math, os, json
import numpy as np
from rcb_client import Robot

OUT='/app/output'
VERT=np.array([0.,1.,0.,0.],dtype=float)  # brush vertical, tip down

def trajectory(points, speed=0.10, dt=0.05, dwell=0):
    """Linear, rate-limited samples between xyz waypoints; points are [x,y,z]."""
    arr=[]
    for a,b in zip(points[:-1],points[1:]):
        a=np.asarray(a,float); b=np.asarray(b,float)
        n=max(1,int(math.ceil(np.linalg.norm(b-a)/(speed*dt))))
        for j in range(1,n+1): arr.append(np.r_[a+(b-a)*(j/n),VERT])
    if dwell:
        arr += [arr[-1].copy() for _ in range(dwell)]
    return np.asarray(arr,dtype=np.float32)

def move(r, points, name, speed=.10, dwell=0, cameras=('canvas_cam','practice_cam','side_cam')):
    P=trajectory(points,speed=speed,dwell=dwell)
    res=r.submit('ee_pose',P,dt=.05,cameras=list(cameras),video='mp4',note=name)
    res.save(os.path.join(OUT,'runs',name))
    print(name, 'meta=',json.dumps(res.meta)[:1600], 'pose=',res.meta.get('proprio',{}).get('now',[None])[7:14])
    return res

def dip_ink(r):
    # Ink well is the visible 20 mm-radius black stone centred at approximately (-0.10,+0.155) m.
    # Its ink surface is about z=.0285m. Submerge the tip by 6mm, then lift clear.
    now=np.asarray(r.get_obs(cameras=['canvas_cam'],video='none').meta['proprio']['now'][7:10],float)
    w=(-.100,.155)
    return move(r,[now.tolist(),[w[0],w[1],.080],[w[0],w[1],.022],[w[0],w[1],.022],[w[0],w[1],.080]],
                'ink_dip',speed=.10,dwell=12,cameras=('scene_cam','side_cam','practice_cam'))

def draw_practice_line(r):
    # Short marks on the unscored practice sheet to measure the dynamic brush footprint.
    # Practice sheet centre=(-.100,-.1856), X to robot's right maps to -world-y,
    # Y toward robot maps to -world-x. These points stay near its centre.
    return move(r,[[-.100,-.1856,.080],[-.100,-.2056,.016],[-.100,-.1656,.016],[-.100,-.1656,.080]],
                'practice_line',speed=.035,dwell=4,cameras=('practice_cam','side_cam','scene_cam'))

if __name__=='__main__':
    r=Robot(); print('status',r.status())
    mode=os.environ.get('ROBO_PHASE','dip')
    if mode=='dip': dip_ink(r)
    elif mode=='practice': draw_practice_line(r)
