OUT='/app/output'
VERT=np.array([0.,1.,0.,0.],dtype=float)  # brush vertical, tip down

def trajectory(points, speed=0.10, dt=0.05, dwell=0):
    """Linear, rate-limited samples between xyz waypoints; points are [x,y,z]."""
    arr=[]
    for a,b in zip(points[:-1],points[1:]):
        a=np.asarray(a,float); b=np.asarray(b,float)
        n=max(1,int(math.ceil(np.linalg.norm(b-a)/(speed*dt))))
        for j in range(1,n+1): arr.append(np.r_[a+(b-a)*(j/n),VERT])
    if dwell:
        arr += [arr[-1].copy() for _ in range(dwell)]
    return np.asarray(arr,dtype=np.float32)

